pts=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
fills=set();
for i,(r,c) in enumerate(pts):
 for R,C in pts[i+1:]:
  if r==R:
   fills.update((r,x) for x in range(min(c,C)+1,max(c,C)))
  if c==C:
   fills.update((x,c) for x in range(min(r,R)+1,max(r,R)))
print(sorted(fills))
G=[[8]*8 for _ in range(30)]
for r,c in pts:G[r][c]=7
for r,c in fills:
 if G[r][c]==8:G[r][c]=3
print('\n'.join(str(row) for row in G))
